5	import org.springframework.stereotype.Repository;
6	
7	import java.util.Optional;
8	
9	/**
10	 * 设备登记表数据访问。
11	 */
12	@Repository
13	public class DeviceRepository {
14	
15	    private final JdbcTemplate jdbc;
16	
17	    public DeviceRepository(JdbcTemplate jdbc) {
18	        this.jdbc = jdbc;
19	    }
20	
21	    public void insert(Device device) {
22	        jdbc.update("INSERT INTO device (device_id, model, current_version, bucket_no) VALUES (?, ?, ?, ?)",
23	                device.deviceId(), device.model(), device.currentVersion(), device.bucketNo());
24	    }
25	
