27	        return jdbc.query("SELECT device_id, model, current_version, bucket_no FROM device WHERE device_id = ?",
28	                (rs, rowNum) -> new Device(rs.getString("device_id"), rs.getString("model"),
29	                        rs.getString("current_version"), rs.getInt("bucket_no")),
30	                deviceId).stream().findFirst();
31	    }
32	
33	    public void updateCurrentVersion(String deviceId, String newVersion) {
34	        jdbc.update("UPDATE device SET current_version = ? WHERE device_id = ?", newVersion, deviceId);
